for lang,(title,subtitle,short,about) in data.items():
    m['title'][lang]=title
    m['subtitle'][lang]=subtitle
    m['shortDescription'][lang]=short
    sentences=about.split('. ')
    m['aboutBook'][lang]=['. '.join(sentences[:3]).rstrip('.')+'.', '. '.join(sentences[3:])]
m['shortDescriptionEditorial']={'source':'human-reviewed','reviewed':True}
m['metadataDraft']={'sourceSha256':m['metadataDraft']['sourceSha256'],'reviewRequired':False,'reviewedAgainst':'source chapters 1–6, conclusion, bibliography; former-project introduction and annexes excluded'}
